       <h1 class="text-5xl sm:text-7xl font-bold tracking-tight text-white">Zsebibaba</h1>
   </header>

   <!-- Kártya konténer - középre igazítva -->
   <div class="min-h-screen flex flex-col items-center justify-center p-4 space-y-8">

       <!-- Külön Időpontfoglalás gomb -->
       <button id="open-calendar-btn" class="button-primary text-lg">
          Időpontfoglalás (25 000 Ft)
       </button>

       <!-- Glassmorphism termékkártya -->
       <div class="glass-card w-72 h-72 p-4 flex flex-col items-center justify-center text-center">
           <div class="product-info">
               <h2 class="text-2xl font-semibold mb-3">Kis csomag</h2>
               <p class="text-lg font-medium text-neutral-300 mb-5">10 000 Ft</p>
               <!-- Vásárlás gomb a termékhez -->
               <button id="purchase-product-btn" class="button-secondary text-base">
                  Vásárlás
               </button>
           </div>
       </div>
   </div>

   <!-- Időpontfoglaló Modális Ablak -->
   <div id="booking-modal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50 opacity-0 invisible">
       <div class="glass-card w-full max-w-lg p-6 sm:p-8 rounded-3xl">
           <div class="flex justify-between items-center mb-6">
               <h3 class="text-2xl font-bold">Időpontfoglalás</h3>
               <button id="close-modal-btn" class="text-gray-400 hover:text-white text-3xl leading-none">×</button>
           </div>

           <!-- Naptár -->
           <div>
               <div class="flex justify-between items-center mb-4">
                   <button id="prev-month-btn" class="p-2 rounded-full hover:bg-white/10 transition-colors">
                       <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns=""><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"></path></svg>
                   </button>
                   <h4 id="current-month-year" class="text-lg font-semibold"></h4>
                   <button id="next-month-btn" class="p-2 rounded-full hover:bg-white/10 transition-colors">
                       <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns=""><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path></svg>
                   </button>
               </div>
               <div class="calendar-grid mb-4">
                   <div class="weekday">H</div><div class="weekday">K</div><div class="weekday">Sze</div><div class="weekday">Cs</div><div class="weekday">P</div><div class="weekday">Szo</div><div class="weekday">V</div>
               </div>
                <div id="calendar-days" class="calendar-grid"></div>
           </div>

           <!-- Idősávok -->
           <div id="time-slots-container" class="mt-6 hidden">
               <h4 class="font-semibold mb-3 text-lg">Válassz időpontot:</h4>
               <div id="time-slots" class="grid grid-cols-3 sm:grid-cols-4 gap-3">
                   <!-- Idősávok dinamikusan lesznek beillesztve -->
               </div>
