           <button id="confirm-booking-btn" class="w-full mt-8 button-primary text-lg transition-opacity opacity-50 cursor-not-allowed" disabled>
               Tovább az utaláshoz (25 000 Ft)
           </button>
       </div>
   </div>

   <script>
       document.addEventListener('DOMContentLoaded', function() {
           // Elemek
           const modal = document.getElementById('booking-modal');
           const openCalendarBtn = document.getElementById('open-calendar-btn');
           const purchaseProductBtn = document.getElementById('purchase-product-btn');
           const closeBtn = document.getElementById('close-modal-btn');
           const prevMonthBtn = document.getElementById('prev-month-btn');
           const nextMonthBtn = document.getElementById('next-month-btn');
           const monthYearEl = document.getElementById('current-month-year');
           const calendarDaysEl = document.getElementById('calendar-days');
           const timeSlotsContainer = document.getElementById('time-slots-container');
           const timeSlotsEl = document.getElementById('time-slots');
           const confirmBtn = document.getElementById('confirm-booking-btn');

           let currentDate = new Date();
           let selectedDate = null;
           let selectedTime = null;

           const availableTimeSlots = ["10:00", "11:00", "14:00", "15:00", "16:00", "18:00"];
           const bookedSlots = {}; // "YYYY-MM-DD": ["HH:MM"]

           // --- KIS CSOMAG VÁSÁRLÁS (10 000 Ft) ---
           purchaseProductBtn.addEventListener('click', () => {
               const accountNumber = '107000314973750901007378';
               const recipientName = 'Zsebeházi Andrea';
               const amount = '10000';
               const currency = 'HUF';
               const comment = 'Zsebibaba Kis Csomag';
               const paymentLink = `iban:HU?acc=${accountNumber}&name=${encodeURIComponent(recipientName)}&amount=${amount}&curr=${currency}&msg=${encodeURIComponent(comment)}`;
               window.location.href = paymentLink;
           });


           // --- Naptár logika ---
           function renderCalendar() {
               const now = new Date();
               now.setHours(0, 0, 0, 0);
               const year = currentDate.getFullYear();
               const month = currentDate.getMonth();
               monthYearEl.textContent = `${year}. ${new Intl.DateTimeFormat('hu-HU', { month: 'long' }).format(currentDate)}`;
               calendarDaysEl.innerHTML = '';
               const firstDayOfMonth = new Date(year, month, 1).getDay();
               const daysInMonth = new Date(year, month + 1, 0).getDate();
               let firstDayIndex = (firstDayOfMonth === 0) ? 6 : firstDayOfMonth - 1;
               for (let i = 0; i < firstDayIndex; i++) {
                   const emptyEl = document.createElement('div');
                   emptyEl.className = 'calendar-day empty';
                   calendarDaysEl.appendChild(emptyEl);
               }
               for (let day = 1; day <= daysInMonth; day++) {
                   const dayEl = document.createElement('div');
                   const dayDate = new Date(year, month, day);
                   dayEl.className = 'calendar-day';
                   dayEl.textContent = day;
                   if (dayDate < now) {
                       dayEl.classList.add('disabled');
                   } else {
                       dayEl.addEventListener('click', () => {
                           if(selectedDate && selectedDate.toDateString() === dayDate.toDateString()) {
                               selectedDate = null;
                               selectedTime = null;
                               timeSlotsContainer.classList.add('hidden');
                           } else {
                               selectedDate = dayDate;
                               selectedTime = null;
                               renderTimeSlots();
                           }
                           updateSelection();
                       });
                   }
                   if (selectedDate && dayDate.toDateString() === selectedDate.toDateString()) {
                       dayEl.classList.add('selected');
                   }
                   calendarDaysEl.appendChild(dayEl);
               }
               updateSelection();
           }

           function renderTimeSlots() {
               timeSlotsEl.innerHTML = '';
               if (!selectedDate) {
                   timeSlotsContainer.classList.add('hidden');
                   return;
               }
               timeSlotsContainer.classList.remove('hidden');
               const dateString = `${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, '0')}-${String(selectedDate.getDate()).padStart(2, '0')}`;
               const todaysBookedSlots = bookedSlots[dateString] || [];
               availableTimeSlots.forEach(time => {
                   const slotEl = document.createElement('div');
                   slotEl.className = 'time-slot border text-center p-2 rounded-lg';
                   slotEl.textContent = time;
                   if (todaysBookedSlots.includes(time)) {
                       slotEl.classList.add('disabled');
                   } else {
                       slotEl.addEventListener('click', () => {
                           selectedTime = time;
                           updateSelection();
                       });
                   }
                   if (selectedTime === time) {
                       slotEl.classList.add('selected');
                   }
                   timeSlotsEl.appendChild(slotEl);
               });
           }

           function updateSelection() {
               document.querySelectorAll('.calendar-day').forEach(el => {
                   el.classList.remove('selected');
                   const day = parseInt(el.textContent);
                   if (selectedDate && day === selectedDate.getDate() && currentDate.getMonth() === selectedDate.getMonth() && currentDate.getFullYear() === selectedDate.getFullYear()) {
                       el.classList.add('selected');
                   }
               });
               document.querySelectorAll('.time-slot').forEach(el => {
                   el.classList.remove('selected');
                   if (selectedTime && el.textContent === selectedTime) {
                       el.classList.add('selected');
                   }
               });
               if (selectedDate && selectedTime) {
                   confirmBtn.disabled = false;
                   confirmBtn.classList.remove('opacity-50', 'cursor-not-allowed');
               } else {
                   confirmBtn.disabled = true;
                   confirmBtn.classList.add('opacity-50', 'cursor-not-allowed');
               }
           }

           // --- Modális ablak vezérlése ---
           function openModal() { modal.classList.remove('opacity-0', 'invisible'); }
           function closeModal() { modal.classList.add('opacity-0', 'invisible'); }

           openCalendarBtn.addEventListener('click', openModal);
           closeBtn.addEventListener('click', closeModal);
           modal.addEventListener('click', (e) => { if(e.target === modal) closeModal(); });

           prevMonthBtn.addEventListener('click', () => {
               currentDate.setMonth(currentDate.getMonth() - 1);
               renderCalendar();
           });
           nextMonthBtn.addEventListener('click', () => {
               currentDate.setMonth(currentDate.getMonth() + 1);
               renderCalendar();
           });

           // --- IDŐPONT FOGLALÁS UTALÁS (25 000 Ft) ---
           confirmBtn.addEventListener('click', () => {
               if (!selectedDate || !selectedTime) return;
               const formattedDate = `${selectedDate.getFullYear()}.${String(selectedDate.getMonth() + 1).padStart(2, '0')}.${String(selectedDate.getDate()).padStart(2, '0')}`;
               const accountNumber = '107000314973750901007378';
               const recipientName = 'Zsebeházi Andrea';
               const amount = '25000';
               const currency = 'HUF';
               const comment = `Zsebibaba Idopontfoglalas - ${formattedDate} ${selectedTime}`;
               const paymentLink = `iban:HU?acc=${accountNumber}&name=${encodeURIComponent(recipientName)}&amount=${amount}&curr=${currency}&msg=${encodeURIComponent(comment)}`;
               window.location.href = paymentLink;
               closeModal();
           });

           // Kezdeti renderelés
           renderCalendar();
       });
   </script>

</body>
</html>

